@ConfigurationProperties("p164.replica")
public record TopologiaReplicaProperties(Map<String, Csi> csiPorHost, Map<String, String> contraparte,
                                         String pack, String usuario) {
    public record Csi(int local, int foraneo) {}

    public String contraparteDe(String host) {
        var destino = contraparte.get(host);
        if (destino == null) throw new HostSinContraparteException(host);   // el fuente deja el host en blanco
        return destino;
    }
}

@Configuration
public class P164JobConfig {

    @Bean
    Job p164(JobRepository repo, Step inicio, TipoProcesoDecider decider,
             Step ctrlDepRet, Step isiLoans, Flow replica, Step pgosPendPe, Step rdormant) {
        Flow todos = new FlowBuilder<Flow>("todos")           // ELSE: orden fijo del fuente
                .start(isiLoans).next(replica).next(ctrlDepRet).next(pgosPendPe).build();
        return new JobBuilder("S500P164", repo)
                .start(inicio)                                 // 40000000-INICIO
                .next(decider)                                 // 50000000-PROCESO
                    .on("CTRLDEPRET").to(ctrlDepRet)
                .from(decider).on("ISILOANS").to(isiLoans)
                .from(decider).on("REPLICA").to(replica)
                .from(decider).on("PGOSPENDPE").to(pgosPendPe)
                .from(decider).on("RDORMANT").to(rdormant)
                .from(decider).on("TODOS").to(todos)
                .end()
                .build();                                      // 70000000-FIN: cierre por listener
    }
}

@Component
class TipoProcesoDecider implements JobExecutionDecider {
    @Override
    public FlowExecutionStatus decide(JobExecution je, StepExecution se) {
        var p = (P164Parametros) je.getExecutionContext().get("parametros");
        return new FlowExecutionStatus(p.proceso().name());
    }
}

@Component
@RequiredArgsConstructor
public class ValidaVersionTasklet implements Tasklet {

    private final HostInfo host;                    // 0000-CALL-HOSTNAME
    private final VersionControlClient versiones;   // 20000100-CHECAME-VERSION

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        if (!host.esPruebas()) {                    // NOT WS-DH-HOSTNAME-PBA
            var r = versiones.checa("S500P164", "25MTP004");
            if (r.cveError() < 0) {
                throw new VersionInvalidaException("ERROR DE VERSION");   // STATUS OF MYSELF = -1
            }
        }
        return RepeatStatus.FINISHED;
    }
}

@Component
@RequiredArgsConstructor
public class FechaBaseTasklet implements Tasklet {

    private final ControlCaptacionRepository b02;   // S500B02CONTROL
    private final CalendarioBancario calendario;    // LOCSUP función 13, formato 12

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var ec = ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext();
        var p = (P164Parametros) ec.get("parametros");
        var control = b02.find().orElseThrow();

        LocalDate base = control.fechaLote();
        LocalDate prox = control.fechaLinea();
        if (p.fecha().isPresent()) {                  // reproceso con fecha del operador
            base = p.fecha().get();
            prox = calendario.avanza(base, 1);        // 20040300-PROYECTA-FECHA
        }
        boolean mensual = prox.getMonthValue() != base.getMonthValue();   // WKS-ES-MENSUAL

        ec.put("fechaBase", base);
        ec.put("esMensual", mensual);
        return RepeatStatus.FINISHED;
    }
}

@Component
@StepScope
public class B52Processor implements ItemProcessor<B52CtrlDepRet, CtrlDepRetDetalle> {

    @Value("#{jobExecutionContext['fechaBase']}") private LocalDate fechaBase;
    @Value("#{jobExecutionContext['esMensual']}") private boolean esMensual;
    @Value("#{jobExecutionContext['csiLocal']}")  private int csiLocal;

    @Override
    public CtrlDepRetDetalle process(B52CtrlDepRet b52) {
        if (!esMensual && !b52.fecUpdate().equals(fechaBase)) {
            return null;                              // diario: sólo lo actualizado en la fecha base
        }
        return AcumuladosVigentes.aplica(b52, fechaBase, csiLocal);   // 50003300 + 50003500
    }
}
// Reader: RepositoryItemReader sobre S500B52CTRLDEPRET (FIND NEXT desde BEGINNING).
// Un status de base distinto de 0 y 1 aborta el step (DMTERMINATE).

public final class AcumuladosVigentes {

    /** 50003500-LIMPIA-ACUMULADOS: el acumulado guardado sólo vale para su día o su mes. */
    static CtrlDepRetDetalle aplica(B52CtrlDepRet b, LocalDate base, int csi) {
        boolean delDia = b.fecAcum().equals(base);
        boolean delMes = YearMonth.from(b.fecAcum()).equals(YearMonth.from(base));
        LocalDate fecAcum = delMes ? b.fecAcum() : null;   // el bloque mensual decide la fecha final

        boolean inteDia = b.fecAcInte().equals(base);
        boolean inteMes = YearMonth.from(b.fecAcInte()).equals(YearMonth.from(base));

        return new CtrlDepRetDetalle(b.numCliente(), csi, b.fecUpdate(), b.tipPer(), b.ubiGeo(),
                delDia ? b.acumDepDia() : BigDecimal.ZERO.setScale(2),
                delMes ? b.acumDepMen() : BigDecimal.ZERO.setScale(2),
                delDia ? b.acumRetDia() : BigDecimal.ZERO.setScale(2),
                delMes ? b.acumRetMen() : BigDecimal.ZERO.setScale(2),
                b.fecCrea(), fecAcum,
                b.limDepDia(), b.limDepMen(), b.limRetDia(), b.limRetMen(),
                b.fecLimDia(), b.fecLimMen(), b.indBloqueo(), b.fecBloqueo(),
                delDia ? b.sdoConDep() : BigDecimal.ZERO.setScale(2),
                inteDia ? b.inteRetDia() : 0, inteMes ? b.inteRetMen() : 0,
                b.fecAcInte(), b.indReplica());
    }
}

@Component
@StepScope
public class B25Processor implements ItemProcessor<B25PagoPendiente, PagoPendienteDetalle> {

    private static final int LONG_REFER = 40;
    @Value("#{jobExecutionContext['fechaBase']}") private LocalDate fechaBase;

    @Override
    public PagoPendienteDetalle process(B25PagoPendiente b25) {
        if (!b25.fechaUltPago().equals(fechaBase)) return null;
        return PagoPendienteDetalle.de(b25.conReferAlfa(sinNulos(b25.referAlfa())));
    }

    /** 00000000-VALIDA-NUL: cada byte @00@ se sustituye por un espacio (no se elimina). */
    static String sinNulos(String refer) {
        var sb = new StringBuilder(LONG_REFER);
        for (int i = 0; i < LONG_REFER; i++) {
            char ch = i < refer.length() ? refer.charAt(i) : ' ';
            sb.append(ch == '\u0000' ? ' ' : ch);
        }
        return sb.toString();
    }
}

@Configuration
@RequiredArgsConstructor
public class ReplicaFlowConfig {

    private final TopologiaReplicaProperties topologia;

    /** Paso 04: ADD (S500)archivo AS (S500)archivo FROM CAPTACION,origen TO CAPTACION,destino. */
    @Bean
    IntegrationFlow enviaReplica(SessionFactory<SftpClient.DirEntry> sftpContraparte) {
        return f -> f
                .handle(Sftp.outboundAdapter(sftpContraparte, FileExistsMode.REPLACE)
                        .remoteDirectory(topologia.pack()))
                .log(LoggingHandler.Level.INFO, "p164.replica");
    }

    /** Paso 05: espera el F05 de la otra cobertura, revisando cada 300 s. */
    @Bean
    Step esperaArchivoForaneo(JobRepository repo, PlatformTransactionManager tx,
                              ArriboArchivoTasklet arribo) {
        return new StepBuilder("esperaArchivoForaneo", repo).tasklet(arribo, tx).build();
    }
}

@Component
@RequiredArgsConstructor
class ArriboArchivoTasklet implements Tasklet {
    private final P164Properties props;            // espera: 300s, max-espera: (no existe en el fuente)
    private final ControlPasosRepository b00;      // S500B00CTRLPASO

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) throws Exception {
        Path foraneo = (Path) ctx.getStepContext().getJobExecutionContext().get("f05");
        if (Files.exists(foraneo)) return RepeatStatus.FINISHED;            // RESIDENT = TRUE
        if (b00.pasoTerminado(130, 181)) throw new FinForzadoException();  // WKS-REPLICA-FIN
        Thread.sleep(props.espera().toMillis());                           // WAIT AND RESET 300
        return RepeatStatus.CONTINUABLE;
    }
}

@Service
@RequiredArgsConstructor
public class ReplicaB52Service {

    private final B52Repository b52;
    private final ProblemasReplicaLog problemas;    // F02-PROBLEMAS

    /** 50004000-B52-STORE. En el fuente un STORE fallido se registra y la transacción se cierra igual. */
    @Transactional
    public void guarda(B52CtrlDepRet registro) {
        try {
            b52.save(registro);
        } catch (DataAccessException e) {
            problemas.registra("ERROR STORE B52", registro.numCliente());
            throw e;                                // aquí se revierte; el original no
        }
    }
}
